actions.body:
{
  "channel": "{{_flow.SLACK_CHANNEL}}",
  "text": "New work item {{issue.key}}: {{issue.fields.summary}}",
  "blocks": [
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "*New work item created*\n<{{baseUrl}}/browse/{{issue.key}}|{{issue.key}}>  {{issue.fields.summary}}"
      }
    },
    {
      "type": "section",
      "fields": [
        {
          "type": "mrkdwn",
          "text": "*Type*\n{{#if issue.fields.issuetype.name}}{{issue.fields.issuetype.name}}{{else}}Unknown{{/if}}"
        },
        {
          "type": "mrkdwn",
          "text": "*Priority*\n{{#if issue.fields.priority.name}}{{issue.fields.priority.name}}{{else}}None{{/if}}"
        },
        {
          "type": "mrkdwn",
          "text": "*Reporter*\n{{#if issue.fields.reporter.displayName}}{{issue.fields.reporter.displayName}}{{else}}Unknown{{/if}}"
        },
        {
          "type": "mrkdwn",
          "text": "*Assignee*\n{{#if issue.fields.assignee.displayName}}{{issue.fields.assignee.displayName}}{{else}}Unassigned{{/if}}"
        }
      ]
    },
    {
      "type": "context",
      "elements": [
        {
          "type": "mrkdwn",
          "text": "{{issue.fields.project.name}} ({{issue.fields.project.key}}) | created by {{#if user.displayName}}{{user.displayName}}{{else}}Unknown{{/if}}"
        }
      ]
    }
  ]
}
